import React from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, LineElement, PointElement,
  LinearScale, CategoryScale, Filler, Tooltip, Legend
} from 'chart.js';

ChartJS.register(LineElement, PointElement, LinearScale, CategoryScale, Filler, Tooltip, Legend);

const timeLabels = ['00:00','04:00','08:00','12:00','16:00','20:00','24:00'];
const rand7 = () => Array.from({ length: 7 }, () => +(Math.random() * .7 + .1).toFixed(2));

const threatColors = {
  Fire: '#fb923c', Smoke: '#94a3b8', Gun: '#f87171',
  Knife: '#facc15', Falling: '#a78bfa', Violence: '#f43f5e', 'Theft Mask': '#fbbf24'
};

const confData = {
  labels: timeLabels,
  datasets: Object.entries(threatColors).map(([name, color]) => ({
    label: name, data: rand7(),
    borderColor: color, borderWidth: 1.5,
    pointRadius: 2, fill: false, tension: .4
  }))
};

const hourLabels = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0') + ':00');
const detData = {
  labels: hourLabels,
  datasets: [{
    data: [12,8,20,15,30,45,28,35,22,18,40,32,15,10,25,38,42,20,14,8,30,18,12,5],
    borderColor: '#3b82f6', borderWidth: 2,
    fill: true, backgroundColor: 'rgba(59,130,246,.08)',
    pointRadius: 0, tension: .4
  }]
};

const gridColor = '#1e2d47';
const tickStyle = { color: '#64748b', font: { size: 9 } };

const baseOpts = {
  animation: false,
  plugins: { legend: { display: false } },
  scales: {
    x: { ticks: { ...tickStyle, maxTicksLimit: 7 }, grid: { color: gridColor } },
    y: { ticks: tickStyle, grid: { color: gridColor } }
  }
};

const confOpts = { ...baseOpts, scales: { ...baseOpts.scales, y: { ...baseOpts.scales.y, min: 0, max: 1, ticks: { ...tickStyle, stepSize: .25 } } } };

export default function ChartsRow() {
  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 10 }}>

      {/* Confidence Score */}
      <div style={{ background: '#151d2e', border: '1px solid #1e2d47', borderRadius: 8, padding: 10 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>
            Confidence Score Graph
          </span>
          <div style={{ display: 'flex', gap: 4 }}>
            {['All Classes', 'Today'].map((opt, i) => (
              <select key={i} style={{ background: '#1a2340', border: '1px solid #253550', color: '#94a3b8', fontSize: 10, padding: '2px 5px', borderRadius: 4 }}>
                <option>{opt}</option>
              </select>
            ))}
          </div>
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 6 }}>
          {Object.entries(threatColors).map(([name, color]) => (
            <span key={name} style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9, color: '#64748b' }}>
              <span style={{ width: 6, height: 6, borderRadius: '50%', background: color, display: 'inline-block' }} />
              {name}
            </span>
          ))}
        </div>
        <Line data={confData} options={confOpts} />
      </div>

      {/* Detections Over Time */}
      <div style={{ background: '#151d2e', border: '1px solid #1e2d47', borderRadius: 8, padding: 10 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>
            Detections Over Time
          </span>
          <div style={{ display: 'flex', gap: 4 }}>
            {['All Classes', 'Today'].map((opt, i) => (
              <select key={i} style={{ background: '#1a2340', border: '1px solid #253550', color: '#94a3b8', fontSize: 10, padding: '2px 5px', borderRadius: 4 }}>
                <option>{opt}</option>
              </select>
            ))}
          </div>
        </div>
        <Line data={detData} options={baseOpts} />
      </div>
    </div>
  );
}
